window.I18N={lang:localStorage.getItem("gj-lang")||"hi",STR:{brand_sub:{hi:"GarbhaJyoti • Garbh Sanskar",en:"GarbhaJyoti • Garbh Sanskar",ne:"गर्भज्योति • गर्भ संस्कार"},nav_home:{hi:"मुख्य",en:"Home",ne:"गृह पृष्ठ"},nav_week:{hi:"सप्ताह यात्रा",en:"Week Journey",ne:"हप्ता यात्रा"},nav_names:{hi:"शिशु नाम",en:"Baby Names",ne:"बच्चाको नाम |"},nav_mantras:{hi:"मंत्र",en:"Mantras",ne:"मन्त्रहरू"},nav_about:{hi:"परिचय",en:"About",ne:"बारेमा"},f_about_t:{hi:"गर्भ ज्योति",en:"GarbhaJyoti",ne:"गर्भज्योति"},f_about_d:{hi:"सप्ताह-दर-सप्ताह गर्भावस्था ज्ञान: शिशु का विकास, मंत्र, प्रार्थनाएँ और प्राचीन कथाएँ।",en:"Week-by-week pregnancy wisdom: your baby's growth, mantras, prayers and timeless stories.",ne:"हप्ता-हप्ता गर्भावस्थाको ज्ञान: तपाईंको बच्चाको वृद्धि, मन्त्र, प्रार्थना र कालातीत कथाहरू।"},f_journey_t:{hi:"यात्रा",en:"Explore",ne:"अन्वेषण गर्नुहोस्"},f_connect_t:{hi:"जुड़ें",en:"Connect",ne:"जडान गर्नुहोस्"},f_yt:{hi:"YouTube चैनल",en:"YouTube channel",ne:"युट्युब च्यानल"},f_newvid:{hi:"नए वीडियो हर सप्ताह",en:"New videos every week",ne:"हरेक हप्ता नयाँ भिडियोहरू"},copyright:{hi:"© 2026 गर्भ ज्योति (GarbhaJyoti) • परंपरा से मार्गदर्शित, AI की सहायता से निर्मित सामग्री",en:"© 2026 GarbhaJyoti • Guided by tradition, crafted with AI",ne:"© २०२६ गर्भज्योति • परम्पराद्वारा निर्देशित, एआई प्रयोग गरी तयार पारिएको"},hero_kicker:{hi:"गर्भ संस्कार • Garbh Sanskar",en:"Garbh Sanskar • Pregnancy Wisdom",ne:"गर्भ संस्कार • गर्भावस्था बुद्धि"},hero_title:{hi:"गर्भ ज्योति",en:"GarbhaJyoti",ne:"गर्भज्योति"},hero_tagline:{hi:"सप्ताह-दर-सप्ताह ज्ञान, माँ और शिशु के लिए",en:"Week-by-week wisdom, for mother and baby",ne:"आमा र बच्चाको लागि हप्ता-हप्ता ज्ञान"},hero_lead:{hi:"आपके शिशु का विकास, मंत्र, प्रार्थनाएँ, संगीत और प्राचीन कथाएँ। गर्भ में पल रही ज्योति का स्वागत कीजिए, हर सप्ताह एक नई सीख के साथ।",en:"Your baby's growth, mantras, prayers, music and timeless stories. Welcome the light growing within, with a new lesson every week.",ne:"तपाईंको बच्चाको वृद्धि, मन्त्र, प्रार्थना, संगीत र कालातीत कथाहरू। हरेक हप्ता नयाँ पाठको साथ भित्र बढिरहेको प्रकाशलाई स्वागत गर्नुहोस्।"},cta_week:{hi:"अपना सप्ताह जानें",en:"Find your week",ne:"आफ्नो हप्ता खोज्नुहोस्"},cta_names:{hi:"शिशु नाम खोजें",en:"Explore baby names",ne:"बच्चाको नाम अन्वेषण गर्नुहोस्"},what_t:{hi:"गर्भ संस्कार क्या है?",en:"What is Garbh Sanskar?",ne:"गर्भ संस्कार भनेको के हो?"},what_sub:{hi:"गर्भ में ही संस्कार, जन्म से पहले शिशु के मन और आत्मा का पोषण",en:"Sanskars in the womb, nurturing the baby's mind and spirit before birth",ne:"गर्भमा हुने संस्कार, जन्मनुभन्दा पहिले बच्चाको मन र आत्मालाई पोषण गर्दै"},what_p1:{hi:"गर्भ संस्कार पूर्वी परंपरा की वह प्राचीन विद्या है जो मानती है कि शिशु की शिक्षा गर्भ से ही आरंभ होती है। चरक संहिता में महीने-दर-महीने भ्रूण के विकास का वर्णन है, और हमारे पुराणों में अभिमन्यु ने माँ के गर्भ में ही चक्रव्यूह का ज्ञान पाया था, जबकि प्रह्लाद ने गर्भ में ही भक्ति के संस्कार ग्रहण किए थे।",en:"Garbh Sanskar is an ancient Eastern traditional science holding that a child's education begins in the womb. The Charaka Samhita describes the month-by-month growth of the embryo, and our Puranas tell how Abhimanyu learned to break the Chakravyuha while still in his mother's womb, and how Prahlad absorbed devotion before birth.",ne:"गर्भ संस्कार एक प्राचीन पूर्वीय परम्परागत विज्ञान हो जसको मान्यता छ कि बच्चाको शिक्षा गर्भबाट सुरु हुन्छ। चरक संहिताले भ्रूणको महिना-दर-महिनाको वृद्धिको वर्णन गर्दछ, र हाम्रा पुराणहरूले अभिमन्युले आमाको गर्भमा हुँदा कसरी चक्रव्यूह तोड्न सिके र प्रह्लादले जन्मनु अघि कसरी भक्ति ग्रहण गरे भनेर बताउँछन्।"},what_p2:{hi:"आधुनिक विज्ञान भी कहता है कि गर्भ में शिशु माँ की आवाज़ सुनता है, संगीत पर प्रतिक्रिया देता है और माँ के भावों को अनुभव करता है। गर्भ ज्योति इसी संगम पर खड़ा है, परंपरा का ज्ञान, विज्ञान की समझ के साथ।",en:"Modern science agrees: in the womb, the baby hears the mother's voice, responds to music, and senses her emotions. GarbhaJyoti stands at this meeting point, the wisdom of tradition, with the understanding of science.",ne:"आधुनिक विज्ञान यस कुरामा सहमत छ: गर्भमा, बच्चाले आमाको आवाज सुन्छ, संगीतमा प्रतिक्रिया दिन्छ, र उनको भावनाहरू महसुस गर्छ। गर्भज्योति यस मिलन बिन्दुमा उभिएको छ, परम्पराको ज्ञान, विज्ञानको बुझाइसँग।"},journey_t:{hi:"आपकी यात्रा",en:"Your journey",ne:"तपाईंको यात्रा"},journey_sub:{hi:"तीन मार्ग, एक लक्ष्य, स्वस्थ, संस्कारी और आनंदित मातृत्व",en:"Three paths, one goal, a healthy, cultured and joyful motherhood",ne:"तीन बाटो, एउटा लक्ष्य, स्वस्थ, सुसंस्कृत र आनन्दित मातृत्व"},c1_t:{hi:"सप्ताह-दर-सप्ताह",en:"Week by week",ne:"हप्ता हप्ता"},c1_d:{hi:"हर सप्ताह शिशु का विकास, एक मंत्र, एक अभ्यास और एक सुझाव। अपनी ड्यू डेट डालें और अपनी यात्रा शुरू करें।",en:"Each week: your baby's growth, a mantra, a practice and a tip. Enter your due date and begin your journey.",ne:"प्रत्येक हप्ता: तपाईंको बच्चाको वृद्धि, एउटा मन्त्र, एउटा अभ्यास र एउटा सुझाव। आफ्नो जन्म मिति प्रविष्ट गर्नुहोस् र आफ्नो यात्रा सुरु गर्नुहोस्।"},c1_go:{hi:"यात्रा शुरू करें →",en:"Start the journey →",ne:"यात्रा सुरु गर्नुहोस् →"},c2_t:{hi:"शिशु नाम संग्रह",en:"Baby name collection",ne:"बच्चाको नाम सङ्ग्रह"},c2_d:{hi:"अर्थ सहित सुंदर संस्कृत नाम। खोजें, छाँटें और अपने शिशु के लिए सबसे शुभ नाम चुनें।",en:"Beautiful Sanskrit names with meanings. Search, filter and choose the most auspicious name for your baby.",ne:"अर्थ सहितको सुन्दर संस्कृत नामहरू। आफ्नो बच्चाको लागि सबैभन्दा शुभ नाम खोज्नुहोस्, फिल्टर गर्नुहोस् र छनौट गर्नुहोस्।"},c2_go:{hi:"नाम खोजें →",en:"Find names →",ne:"नामहरू खोज्नुहोस् →"},c3_t:{hi:"मंत्र और प्रार्थना",en:"Mantras and prayers",ne:"मन्त्र र प्रार्थनाहरू"},c3_d:{hi:"गायत्री मंत्र, संतान गोपाल मंत्र और सायं प्रार्थना, अर्थ सहित, श्रवण ऑडियो के साथ।",en:"Gayatri mantra, Santan Gopal mantra and the evening prayer, with meanings and listening audio.",ne:"गायत्री मन्त्र, सन्तन गोपाल मन्त्र र साँझको प्रार्थना, अर्थ र सुन्ने अडियो सहित।"},c3_go:{hi:"सुनें और पढ़ें →",en:"Listen and read →",ne:"सुन्नुहोस् र पढ्नुहोस् →"},vid_t:{hi:"वीडियो श्रृंखला",en:"Video series",ne:"भिडियो श्रृंखला"},vid_sub:{hi:"छोटे वीडियो, गहरी सीख, हर सप्ताह नया वीडियो",en:"Short videos, deep lessons, a new video every week",ne:"छोटो भिडियोहरू, गहिरो पाठहरू, हरेक हप्ता एउटा नयाँ भिडियो"},cta_sub:{hi:"YouTube पर सब्सक्राइब करें",en:"Subscribe on YouTube",ne:"YouTube मा सदस्यता लिनुहोस्"},w_title:{hi:"सप्ताह-दर-सप्ताह यात्रा",en:"Week-by-week journey",ne:"हप्ता-हप्ता यात्रा"},w_sub:{hi:"हर सप्ताह: शिशु का विकास, एक अभ्यास और एक सुझाव",en:"Every week: your baby's growth, a practice and a tip",ne:"हरेक हप्ता: तपाईंको बच्चाको वृद्धि, एउटा अभ्यास र एउटा सुझाव"},tr_t:{hi:"आप किस सप्ताह में हैं?",en:"Which week are you in?",ne:"तपाईं कुन हप्तामा हुनुहुन्छ?"},tr_d:{hi:"अपनी ड्यू डेट (प्रसव की संभावित तिथि) डालें, हम आपका सप्ताह बता देंगे",en:"Enter your due date, we'll tell you your week",ne:"आफ्नो अन्तिम मिति प्रविष्ट गर्नुहोस्, हामी तपाईंलाई तपाईंको हप्ता बताउनेछौं।"},tr_btn:{hi:"मेरा सप्ताह देखें",en:"Show my week",ne:"मेरो हप्ता देखाउनुहोस्"},tr_pick:{hi:"कृपया तिथि चुनें",en:"Please pick a date",ne:"कृपया मिति छान्नुहोस्।"},tr_early:{hi:"बधाई! आपकी यात्रा अभी शुरू होने वाली है, पहला सप्ताह देखें।",en:"Congratulations! Your journey is about to begin, see week 1.",ne:"बधाई छ! तपाईंको यात्रा सुरु हुन लागेको छ, हप्ता १ हेर्नुहोस्।"},tr_late:{hi:"आपकी ड्यू डेट निकल चुकी है, शिशु के जन्म की बधाई!",en:"Your due date has passed, congratulations on your baby!",ne:"तपाईंको सुत्केरी हुने मिति सकियो, तपाईंको बच्चाको लागि बधाई छ!"},tr_now:{hi:"बधाई! आप अभी {w}वें सप्ताह में हैं।",en:"Congratulations! You are in week {w}.",ne:"बधाई छ! तपाईं हप्ता {w} मा हुनुहुन्छ।"},lbl_growth:{hi:"शिशु का विकास",en:"Your baby's growth",ne:"तपाईंको बच्चाको वृद्धि"},lbl_sadhana:{hi:"इस सप्ताह का अभ्यास",en:"This week's practice",ne:"यस हप्ताको अभ्यास"},lbl_tip:{hi:"सुझाव",en:"Tip",ne:"सुझाव"},wk_label:{hi:"{w}वां सप्ताह",en:"Week {w}",ne:"हप्ता {w}"},soon_t:{hi:"{w}वां सप्ताह, जल्द आ रहा है",en:"Week {w}, coming soon",ne:"हप्ता {w}, चाँडै आउँदैछ"},soon_d:{hi:"हम हर सप्ताह नई सामग्री जोड़ रहे हैं। नए वीडियो सबसे पहले पाने के लिए",en:"We add new content every week. To get new videos first",ne:"हामी हरेक हप्ता नयाँ सामग्री थप्छौं। नयाँ भिडियोहरू पहिले प्राप्त गर्न"},soon_btn:{hi:"YouTube पर जुड़ें",en:"Join on YouTube",ne:"YouTube मा सामेल हुनुहोस्"},n_title:{hi:"शिशु नाम संग्रह",en:"Baby name collection",ne:"बच्चाको नाम सङ्ग्रह"},n_sub:{hi:"अर्थ सहित सुंदर संस्कृत नाम, खोजें, छाँटें, चुनें",en:"Beautiful Sanskrit names with meanings, search, filter, choose",ne:"अर्थ, खोज, फिल्टर, छनौट सहितको सुन्दर संस्कृत नामहरू"},search_ph:{hi:"नाम खोजें… (जैसे: दिया, Aarav)",en:"Search names… (e.g. Diya, Aarav)",ne:"नामहरू खोज्नुहोस्... (जस्तै दिया, आरव)"},pill_all:{hi:"सभी",en:"All",ne:"सबै"},pill_boy:{hi:"बालक",en:"Boy",ne:"केटा"},pill_girl:{hi:"बालिका",en:"Girl",ne:"केटी"},pill_both:{hi:"दोनों",en:"Unisex",ne:"युनिसेक्स"},no_res:{hi:"कोई नाम नहीं मिला, कुछ और खोजकर देखें।",en:"No names found, try another search.",ne:"कुनै नाम भेटिएन, अर्को खोजी प्रयास गर्नुहोस्।"},names_count:{hi:"{n} नाम",en:"{n} names",ne:"{n} नामहरू"},soon_names:{hi:"🪔 जल्द आ रहा है: नक्षत्र के अनुसार नाम खोज, जन्म विवरण डालें, शुभ अक्षर पाएं।",en:"🪔 Coming soon: find names by nakshatra, enter birth details, get auspicious syllables.",ne:"🪔 चाँडै आउँदैछ: नक्षत्र अनुसार नामहरू खोज्नुहोस्, जन्म विवरणहरू प्रविष्ट गर्नुहोस्, शुभ अक्षरहरू प्राप्त गर्नुहोस्।"},nak_title:{hi:"नक्षत्र से नाम खोजें",en:"Find names by nakshatra",ne:"नक्षत्र अनुसार नाम खोज्नुहोस्"},nak_sub:{hi:"जन्म तिथि और समय डालें, जानें आपका नक्षत्र, चरण और शुभ अक्षर।",en:"Enter birth date and time to find your nakshatra, pada and auspicious syllables.",ne:"आफ्नो नक्षत्र, पद र शुभ अक्षरहरू फेला पार्न जन्म मिति र समय प्रविष्ट गर्नुहोस्।"},nak_date:{hi:"जन्म तिथि",en:"Birth date",ne:"जन्म मिति"},nak_time:{hi:"जन्म समय",en:"Birth time",ne:"जन्म समय"},nak_tz:{hi:"समय क्षेत्र",en:"Time zone",ne:"समय क्षेत्र"},nak_go:{hi:"नक्षत्र जानें",en:"Find nakshatra",ne:"नक्षत्र खोज्नुहोस्"},nak_need:{hi:"कृपया जन्म तिथि डालें।",en:"Please enter the birth date.",ne:"कृपया जन्म मिति प्रविष्ट गर्नुहोस्।"},nak_lb_nak:{hi:"नक्षत्र",en:"Nakshatra",ne:"नक्षत्र"},nak_lb_pada:{hi:"चरण",en:"Pada",ne:"पाडा"},nak_lb_rashi:{hi:"चंद्र राशि",en:"Moon sign",ne:"चन्द्रमा चिन्ह"},nak_lb_syl:{hi:"शुभ अक्षर",en:"Auspicious syllables",ne:"शुभ अक्षरहरू"},nak_yours:{hi:"आपके चरण का अक्षर",en:"Your pada syllable",ne:"तपाईंको पदा अक्षर"},nak_show:{hi:"इन अक्षरों के नाम दिखाएं",en:"Show names with these syllables",ne:"यी अक्षरहरू भएका नामहरू देखाउनुहोस्"},nak_clear:{hi:"फ़िल्टर हटाएं",en:"Clear filter",ne:"फिल्टर खाली गर्नुहोस्"},nak_approx:{hi:"यह गणना अनुमानित है (लाहिड़ी अयनांश)। चरण सीमा के पास जन्म होने पर कृपया किसी ज्योतिषी से पुष्टि करें।",en:"Approximate calculation (Lahiri ayanamsa). If birth was near a pada boundary, please confirm with a jyotishi.",ne:"अनुमानित गणना (लाहिरी अयनम्सा)। यदि जन्म पद सीमा नजिकै भएको हो भने, कृपया ज्योतिषीसँग पुष्टि गर्नुहोस्।"},nav_stories:{hi:"कथाएँ",en:"Stories",ne:"कथाहरू"},nav_muhurta:{hi:"शुभ मुहूर्त",en:"Muhurta",ne:"शुभ मुहूर्त"},c4_t:{hi:"शुभ मुहूर्त",en:"Auspicious Birth Timing",ne:"शुभ मुहूर्त"},c4_d:{hi:"नियोजित प्रसव के लिए शास्त्रीय मार्गदर्शन: तिथि, नक्षत्र और शुभ समय।",en:"Classical guidance for a planned delivery: tithi, nakshatra and auspicious timing.",ne:"योजनाबद्ध प्रसवका लागि शास्त्रीय मार्गदर्शन: तिथि, नक्षत्र र शुभ समय।"},c4_go:{hi:"मुहूर्त खोजें →",en:"Find timing →",ne:"मुहूर्त खोज्नुहोस् →"},mu_title:{hi:"शुभ मुहूर्त: प्रसव का शुभ समय",en:"Shubh Muhurta: Auspicious Birth Timing",ne:"शुभ मुहूर्त: प्रसवको शुभ समय"},mu_sub:{hi:"जब डॉक्टर पहले से ही नियोजित प्रसव की समय-सीमा दे चुके हों, तो परंपरागत ज्योतिष और अंकशास्त्र के अनुसार सबसे शुभ दिन और समय चुनें।",en:"When your doctor has already given you a window for a planned delivery, choose the most auspicious day and time by traditional astrology and numerology.",ne:"जब डाक्टरले योजनाबद्ध प्रसवका लागि समय-सीमा दिइसक्नुभएको छ, परम्परागत ज्योतिष र अंकशास्त्र अनुसार सबैभन्दा शुभ दिन र समय छान्नुहोस्।"},mu_disc_t:{hi:"पहले एक आवश्यक निवेदन",en:"An important note first",ne:"पहिले एउटा आवश्यक अनुरोध"},mu_disc_med:{hi:"यह उपकरण वैकल्पिक सिजेरियन को बढ़ावा नहीं देता। सिजेरियन एक बड़ा ऑपरेशन है, जिसमें माँ और शिशु दोनों के लिए जोखिम होते हैं। प्रसव का तरीका और तारीख हमेशा आपके डॉक्टर तय करेंगे, चिकित्सा आवश्यकता के आधार पर। इस उपकरण का उपयोग तभी करें जब आपके डॉक्टर ने सुरक्षित तारीखों की समय-सीमा पहले से दे दी हो।",en:"This tool does not promote elective caesarean delivery. A caesarean is major surgery, with risks for both mother and baby. Your doctor always decides the method and date of delivery, based on medical need. Use this tool only after your doctor has given you a safe window of dates.",ne:"यो उपकरणले ऐच्छिक शल्यक्रिया प्रसवलाई प्रोत्साहन दिँदैन। शल्यक्रिया प्रसव ठूलो शल्यक्रिया हो, जसमा आमा र बच्चा दुवैका लागि जोखिम हुन्छन्। प्रसवको विधि र मिति सधैं तपाईंको डाक्टरले चिकित्सकीय आवश्यकताका आधारमा तय गर्नुहुन्छ। तपाईंको डाक्टरले सुरक्षित मितिहरूको समय-सीमा दिइसकेपछि मात्र यो उपकरण प्रयोग गर्नुहोस्।"},mu_disc_astro:{hi:"गणना अनुमानित खगोलीय सूत्रों पर आधारित है (लाहिड़ी अयनांश, अनुमानित)। यह किसी योग्य ज्योतिषी के परामर्श का विकल्प नहीं है। अंतिम निर्णय से पहले अपने ज्योतिषी से अवश्य परामर्श करें।",en:"Calculations use approximate astronomical formulas (Lahiri ayanamsa, estimated). This is not a substitute for a qualified jyotishi. Please consult your astrologer before the final decision.",ne:"गणना अनुमानित खगोलीय सूत्रहरूमा आधारित छ (लाहिड़ी अयनांश, अनुमानित)। यो योग्य ज्योतिषीको परामर्शको विकल्प होइन। अन्तिम निर्णयअघि आफ्नो ज्योतिषीसँग अवश्य परामर्श गर्नुहोस्।"},mu_from:{hi:"डॉक्टर की समय-सीमा: प्रारंभ तिथि",en:"Doctor's window: start date",ne:"डाक्टरको समय-सीमा: सुरु मिति"},mu_to:{hi:"अंतिम तिथि",en:"End date",ne:"अन्तिम मिति"},mu_tz:{hi:"अस्पताल का समय क्षेत्र",en:"Hospital time zone",ne:"अस्पतालको समय क्षेत्र"},mu_city:{hi:"शहर (अक्षांश-देशांतर स्वतः भर जाएगा)",en:"City (fills latitude/longitude)",ne:"सहर (अक्षांश-देशान्तर स्वतः भरिन्छ)"},mu_custom:{hi:"या अपने अक्षांश-देशांतर लिखें",en:"Or enter latitude/longitude",ne:"वा आफ्नो अक्षांश-देशान्तर लेख्नुहोस्"},mu_lat:{hi:"अक्षांश",en:"Latitude",ne:"अक्षांश"},mu_lon:{hi:"देशांतर (पूर्व +)",en:"Longitude (east +)",ne:"देशान्तर (पूर्व +)"},mu_mom_t:{hi:"माँ की जन्म जानकारी (वैकल्पिक, तारा-चंद्र बल के लिए)",en:"Mother's birth details (optional, for tara and chandra bala)",ne:"आमाको जन्म विवरण (वैकल्पिक, तारा-चन्द्र बलका लागि)"},mu_mom_nak:{hi:"माँ का जन्म नक्षत्र",en:"Mother's birth nakshatra",ne:"आमाको जन्म नक्षत्र"},mu_mom_rashi:{hi:"माँ की चंद्र राशि",en:"Mother's Moon sign",ne:"आमाको चन्द्र राशि"},mu_notset:{hi:"ज्ञात नहीं",en:"Not known",ne:"थाहा छैन"},mu_btn:{hi:"शुभ दिन खोजें",en:"Find auspicious days",ne:"शुभ दिनहरू खोज्नुहोस्"},mu_err_dates:{hi:"कृपया प्रारंभ और अंतिम, दोनों तिथियाँ चुनें।",en:"Please choose both a start and an end date.",ne:"कृपया सुरु र अन्तिम दुवै मिति छान्नुहोस्।"},mu_err_range:{hi:"समय-सीमा अधिकतम 45 दिन की हो सकती है।",en:"The window can be at most 45 days.",ne:"समय-सीमा अधिकतम ४५ दिनको हुन सक्छ।"},mu_best:{hi:"सबसे शुभ दिन पहले दिखाए गए हैं",en:"Best days shown first",ne:"सबैभन्दा शुभ दिन पहिले देखाइएका छन्"},mu_score:{hi:"अंक",en:"Score",ne:"अंक"},mu_v_uttam:{hi:"उत्तम",en:"Excellent",ne:"उत्तम"},mu_v_shubh:{hi:"शुभ",en:"Good",ne:"शुभ"},mu_v_madhyam:{hi:"मध्यम",en:"Average",ne:"मध्यम"},mu_v_avoid:{hi:"बचें",en:"Avoid",ne:"बच्नुहोस्"},mu_tithi:{hi:"तिथि",en:"Tithi",ne:"तिथि"},mu_vara:{hi:"वार",en:"Weekday",ne:"बार"},mu_nak:{hi:"नक्षत्र",en:"Nakshatra",ne:"नक्षत्र"},mu_yoga:{hi:"योग",en:"Yoga",ne:"योग"},mu_karana:{hi:"करण",en:"Karana",ne:"करण"},mu_num:{hi:"भाग्यांक",en:"Bhagyank (destiny no.)",ne:"भाग्याङ्क"},mu_mulank:{hi:"मूलांक",en:"Mulank (birth no.)",ne:"मूलाङ्क"},mu_tara:{hi:"तारा बल",en:"Tara bala",ne:"तारा बल"},mu_chandra:{hi:"चंद्र बल",en:"Chandra bala",ne:"चन्द्र बल"},mu_paksha:{hi:"पक्ष",en:"Paksha",ne:"पक्ष"},mu_paksha_shukla:{hi:"शुक्ल",en:"Shukla",ne:"शुक्ल"},mu_paksha_krishna:{hi:"कृष्ण",en:"Krishna",ne:"कृष्ण"},mu_avoid_t:{hi:"इन समयों से बचें",en:"Avoid these times",ne:"यी समयहरूबाट बच्नुहोस्"},mu_rahu:{hi:"राहुकाल",en:"Rahu Kalam",ne:"राहुकाल"},mu_yama:{hi:"यमगंडम",en:"Yamagandam",ne:"यमगण्डम्"},mu_rise:{hi:"सूर्योदय",en:"Sunrise",ne:"सूर्योदय"},mu_set:{hi:"सूर्यास्त",en:"Sunset",ne:"सूर्यास्त"},mu_win_t:{hi:"सुझाए गए शुभ समय",en:"Suggested auspicious windows",ne:"सुझाव गरिएका शुभ समयहरू"},mu_lagna:{hi:"लग्न",en:"Lagna",ne:"लग्न"},mu_why:{hi:"अंक क्यों",en:"Why this score",ne:"यो अंक किन"},mu_how_t:{hi:"गणना कैसे होती है",en:"How it is calculated",ne:"गणना कसरी हुन्छ"},mu_how_d:{hi:"प्रत्येक दिन का मूल्यांकन शास्त्रीय मुहूर्त-शास्त्र की परंपरा में होता है (जैसे मुहूर्त चिंतामणि के सिद्धांत): शुक्ल पक्ष, शुभ तिथियाँ (रिक्ता, अमावस्या और ग्रहण से बचकर), शुभ नक्षत्र (गंडमूल और संक्रांति से बचकर), शुभ योग और करण, वार, तारा-चंद्र बल, राहुकाल और यमगंडम से मुक्त समय, स्थिर लग्न, अभिजित मुहूर्त, शुभ होरा और तारीख का मूलांक। सूर्योदय, राहुकाल और लग्न की गणना आपके चुने हुए समय क्षेत्र और स्थान के अनुसार होती है। पूर्ण कुंडली के सूक्ष्म योगों (जैसे केमद्रुम, कालसर्प, ग्रहों की दृष्टि और बल, मंगल दोष) की गणना इसमें नहीं है, इनके लिए कृपया योग्य ज्योतिषी से परामर्श करें।",en:"Each day is scored in the tradition of classical electional astrology (on the lines of Muhurta Chintamani): Shukla paksha, auspicious tithis (avoiding Rikta, Amavasya and eclipses), auspicious nakshatras (avoiding Gandmoola and Sankranti days), good yogas and karanas, weekday, tara and chandra bala, time free of Rahu Kalam and Yamagandam, fixed lagna, Abhijit muhurta, benefic horas, and the date root number. Sunrise, Rahu Kalam and lagna are computed for your chosen time zone and location. Subtle chart yogas (Kemadruma, Kaalsarpa, planetary aspects and strengths, Mangal Dosha) are beyond this calculator, please consult a qualified jyotishi for those.",ne:"प्रत्येक दिनको मूल्यांकन शास्त्रीय मुहूर्त-शास्त्रको परम्परामा हुन्छ (मुहूर्त चिन्तामणि जस्ता सिद्धान्त अनुसार): शुक्ल पक्ष, शुभ तिथिहरू (रिक्ता, औंसी र ग्रहणबाट बचेर), शुभ नक्षत्र (गण्डमूल र संक्रान्तिबाट बचेर), शुभ योग र करण, बार, तारा-चन्द्र बल, राहुकाल र यमगण्डम्‌बाट मुक्त समय, स्थिर लग्न, अभिजित मुहूर्त, शुभ होरा र मितिको मूलांक। तपाईंले छान्नुभएको समय क्षेत्र र स्थान अनुसार सूर्योदय, राहुकाल र लग्नको गणना हुन्छ। पूर्ण कुण्डलीका सूक्ष्म योगहरू (केमद्रुम, कालसर्प, ग्रह दृष्टि र बल, मंगल दोष) यस गणनामा छैनन्, यिनका लागि कृपया योग्य ज्योतिषीसँग परामर्श गर्नुहोस्।"},mu_win_note:{hi:"सुझाए गए समय राहुकाल और यमगंडम से बाहर हैं, और उनमें लग्न स्थिर राशि में है।",en:"Suggested windows fall outside Rahu Kalam and Yamagandam, with lagna in a fixed sign.",ne:"सुझाव गरिएका समयहरू राहुकाल र यमगण्डम्‌भन्दा बाहिर छन्, र लग्न स्थिर राशिमा छ।"},mu_abhijit:{hi:"अभिजित मुहूर्त",en:"Abhijit Muhurta",ne:"अभिजित मुहूर्त"},mu_hora:{hi:"होरा",en:"Hora",ne:"होरा"},mu_fav:{hi:"अनुकूल",en:"Favorable",ne:"अनुकूल"},mu_unfav:{hi:"प्रतिकूल",en:"Unfavorable",ne:"प्रतिकूल"},mu_neu:{hi:"तटस्थ",en:"Neutral",ne:"तटस्थ"},st_title:{hi:"गर्भ के लिए पौराणिक कथाएँ",en:"Mythology Stories for the Womb",ne:"गर्भको लागि पौराणिक कथाहरू"},st_sub:{hi:"सप्ताह 18 से प्रसव तक, हर सप्ताह सुनाने के लिए हिंदू धर्म की 50 मधुर कथाएँ। शिशु आपकी आवाज़ सुनता है, उसे प्रेम, साहस और भक्ति की कहानियाँ सुनाइए।",en:"50 gentle stories from Hindu tradition to recite from week 18 until delivery. Your baby hears your voice, so tell it tales of love, courage and devotion.",ne:"हप्ता १८ देखि बच्चा जन्मिएसम्म सुनाउन हिन्दू परम्पराका ५० कोमल कथाहरू। तपाईंको बच्चाले तपाईंको आवाज सुन्छ, त्यसैले उसलाई प्रेम, साहस र भक्तिका कथाहरू सुनाउनुहोस्।"},st_search:{hi:"कथा खोजें...",en:"Search stories...",ne:"कथाहरू खोज्नुहोस्..."},st_all_weeks:{hi:"सभी सप्ताह",en:"All weeks",ne:"सबै हप्ताहरू"},st_all_themes:{hi:"सभी विषय",en:"All themes",ne:"सबै विषयवस्तुहरू"},st_week_badge:{hi:"सप्ताह {w}",en:"Week {w}",ne:"हप्ता {w}"},st_read:{hi:"कथा पढ़ें",en:"Read story",ne:"कथा पढ्नुहोस्"},st_moral:{hi:"सीख",en:"Moral",ne:"नैतिक"},st_listen:{hi:"सुनें",en:"Listen",ne:"सुन्नुहोस्"},st_watch:{hi:"वीडियो देखें",en:"Watch video",ne:"भिडियो हेर्नुहोस्"},st_stop:{hi:"रोकें",en:"Stop",ne:"रोक्नुहोस्"},st_prev:{hi:"← पिछली",en:"← Previous",ne:"← अघिल्लो"},st_next:{hi:"अगली →",en:"Next →",ne:"अर्को →"},st_close:{hi:"बंद करें",en:"Close",ne:"बन्द गर्नुहोस्"},st_no_res:{hi:"कोई कथा नहीं मिली। खोज बदलकर देखें।",en:"No stories found. Try a different search.",ne:"कुनै पनि कथा भेटिएन। फरक खोज प्रयास गर्नुहोस्।"},st_wk_link:{hi:"इस सप्ताह सुनाने की कथाएँ",en:"Stories to recite this week",ne:"यस हप्ता पढ्नु पर्ने कथाहरू"},th_krishna:{hi:"कृष्ण",en:"Krishna",ne:"कृष्ण"},th_rama:{hi:"राम",en:"Rama",ne:"रामा"},th_shiva:{hi:"शिव",en:"Shiva",ne:"शिव"},th_devi:{hi:"देवी",en:"Devi",ne:"देवी"},th_vishnu:{hi:"विष्णु",en:"Vishnu",ne:"विष्णु"},th_hanuman:{hi:"हनुमान",en:"Hanuman",ne:"हनुमान"},th_ganesha:{hi:"गणेश",en:"Ganesha",ne:"गणेश"},th_wisdom:{hi:"ज्ञान",en:"Wisdom",ne:"बुद्धि"},th_devotion:{hi:"भक्ति",en:"Devotion",ne:"भक्ति"},nak_no_names:{hi:"इन अक्षरों से शुरू होने वाला कोई नाम संग्रह में नहीं मिला।",en:"No names in the collection start with these syllables.",ne:"सङ्ग्रहमा रहेका कुनै पनि नाम यी अक्षरहरूबाट सुरु हुँदैनन्।"},flt_letter:{hi:"शुरुआती अक्षर",en:"Starting letter",ne:"सुरुवाती पत्र"},flt_syl:{hi:"शब्दांश",en:"Syllables",ne:"अक्षरहरू"},flt_all:{hi:"सभी",en:"All",ne:"सबै"},sort_label:{hi:"क्रम",en:"Sort",ne:"क्रमबद्ध गर्नुहोस्"},sort_az:{hi:"अ से ज्ञ",en:"A to Z",ne:"क देखि ञ"},sort_syl_asc:{hi:"कम शब्दांश पहले",en:"Fewest syllables first",ne:"सबैभन्दा कम अक्षरहरू पहिले"},sort_syl_desc:{hi:"अधिक शब्दांश पहले",en:"Most syllables first",ne:"धेरैजसो अक्षरहरू पहिले"},page_prev:{hi:"पिछला",en:"Prev",ne:"अघिल्लो"},page_next:{hi:"अगला",en:"Next",ne:"अर्को"},page_of:{hi:"पृष्ठ {p} / {t}",en:"Page {p} of {t}",ne:"पृष्ठ {p} को {t}"},tag_compound:{hi:"पारंपरिक शैली",en:"Traditional style",ne:"परम्परागत शैली"},mix_title:{hi:"माता-पिता के नाम मिलाएँ",en:"Blend the parents' names",ne:"आमाबाबुको नाम मिलाउनुहोस्"},mix_sub:{hi:"दोनों नाम लिखें, हम उनकी ध्वनियाँ मिलाकर सबसे करीबी असली नाम पहले दिखाएँगे।",en:"Type both names, we blend their sounds and show the closest real names first.",ne:"दुबै नामहरू टाइप गर्नुहोस्, हामी तिनीहरूको ध्वनि मिसाउँछौं र पहिले नजिकको वास्तविक नामहरू देखाउँछौं।"},mix_father:{hi:"पिता का नाम",en:"Father's name",ne:"बुबाको नाम"},mix_mother:{hi:"माता का नाम",en:"Mother's name",ne:"आमाको नाम"},mix_initial:{hi:"इस अक्षर से शुरू हो (वैकल्पिक)",en:"Must start with (optional)",ne:"(वैकल्पिक) बाट सुरु गर्नुपर्छ"},mix_go:{hi:"नाम मिलाएँ",en:"Blend names",ne:"नामहरू मिलाउनुहोस्"},mix_match:{hi:"सबसे करीबी असली नाम",en:"Closest real names",ne:"नजिकका वास्तविक नामहरू"},mix_creative:{hi:"रचनात्मक मेल",en:"Creative blends",ne:"रचनात्मक मिश्रणहरू"},mix_review:{hi:"रचनात्मक मेल नए सुझाव हैं, पारंपरिक नाम नहीं। कृपया परिवार के बड़ों से सलाह लें।",en:"Creative blends are new ideas, not traditional names. Please review them with family elders.",ne:"रचनात्मक मिश्रणहरू नयाँ विचारहरू हुन्, परम्परागत नामहरू होइनन्। कृपया परिवारका अग्रजहरूसँग तिनीहरूको समीक्षा गर्नुहोस्।"},mix_none:{hi:"मेल देखने के लिए दोनों नाम लिखें।",en:"Enter both names to see blends.",ne:"मिश्रणहरू हेर्न दुवै नामहरू प्रविष्ट गर्नुहोस्।"},m_title:{hi:"मंत्र और प्रार्थना",en:"Mantras and prayers",ne:"मन्त्र र प्रार्थनाहरू"},m_sub:{hi:"अर्थ सहित पढ़ें, ऑडियो के साथ सुनें और दोहराएं",en:"Read with meanings, listen with audio, and repeat",ne:"अर्थसहित पढ्नुहोस्, अडियोसहित सुन्नुहोस्, र दोहोर्याउनुहोस्"},man1_t:{hi:"गायत्री मंत्र",en:"Gayatri Mantra",ne:"गायत्री मन्त्र"},man1_when:{hi:"🪔 कब: रोज़ सुबह स्नान के बाद, 11 या 21 बार",en:"🪔 When: every morning after bathing, 11 or 21 times",ne:"🪔 कहिले: हरेक बिहान नुहाइसकेपछि, ११ वा २१ पटक"},man1_m:{hi:"हम उस तेजस्वी सूर्य के श्रेष्ठ तेज का ध्यान करते हैं, जो हमारी बुद्धि को सन्मार्ग पर प्रेरित करे। गर्भावस्था में यह मंत्र मन को शांत करता है और सकारात्मक ऊर्जा का संचार करता है।",en:"We meditate on the supreme radiance of the radiant sun, which inspires our intellect toward the right path. In pregnancy this mantra calms the mind and spreads positive energy.",ne:"हामी तेजस्वी सूर्यको सर्वोच्च तेजको ध्यान गर्छौं, जसले हाम्रो बुद्धिलाई सही मार्गमा डोऱ्याउछ। गर्भावस्थामा यो मन्त्रले मनलाई शान्त पार्छ र सकारात्मक ऊर्जा फैलाउँछ।"},man2_t:{hi:"संतान गोपाल मंत्र",en:"Santan Gopal Mantra",ne:"सन्तन गोपाल मन्त्र"},man2_when:{hi:"🪔 कब: संतान की कामना या गर्भ की रक्षा हेतु, सुबह-शाम",en:"🪔 When: for the wish of a child or the protection of the womb, morning and evening",ne:"🪔 कहिले: बच्चाको इच्छा वा गर्भको सुरक्षाको लागि, बिहान र साँझ"},man2_m:{hi:"हे देवकीनंदन गोविंद, हे जगत के स्वामी वासुदेव! मुझे संतान दीजिए, हे कृष्ण! मैं आपकी शरण में हूँ। यह मंत्र विशेष रूप से गर्भ की रक्षा और स्वस्थ संतान हेतु जपा जाता है।",en:"O Govinda, son of Devaki, O Vasudeva, lord of the universe! Grant me a child, O Krishna! I take refuge in you. This mantra is chanted especially for the protection of the womb and a healthy child.",ne:"हे देवकीका पुत्र गोविन्द, हे ब्रह्माण्डका स्वामी वासुदेव! मलाई सन्तान दिनुहोस्, हे कृष्ण! म तपाईंको शरणमा पर्छु। यो मन्त्र विशेष गरी गर्भ र स्वस्थ सन्तानको सुरक्षाको लागि जप गरिन्छ।"},man3_t:{hi:"शुभं करोति, सायं प्रार्थना",en:"Shubham Karoti, evening prayer",ne:"शुभम करोती, साँझ प्रार्थना"},man3_when:{hi:"🪔 कब: रोज़ शाम दीप जलाते समय, परिवार के साथ",en:"🪔 When: every evening while lighting the lamp, with family",ne:"🪔 कहिले: हरेक साँझ परिवारसँगै बत्ती बाल्दा"},man3_m:{hi:"जो शुभ करता है, कल्याण, आरोग्य और धन-संपदा देता है, और शत्रु बुद्धि का नाश करता है, उस दीप ज्योति को नमस्कार। शाम का दीप और यह प्रार्थना घर में शांति लाती है।",en:"Salutations to the flame of the lamp, which brings auspiciousness, welfare, health and wealth, and destroys hostile thoughts. The evening lamp and this prayer bring peace to the home.",ne:"शुभ, कल्याण, स्वास्थ्य र धन ल्याउँछ र शत्रुतापूर्ण विचारहरूलाई नष्ट गर्छ, दीपकको ज्वालालाई नमस्कार। साँझको दीपक र यो प्रार्थनाले घरमा शान्ति ल्याउँछ।"},meaning_t:{hi:"अर्थ",en:"Meaning",ne:"अर्थ"},howto_t:{hi:"जप कैसे करें?",en:"How to chant?",ne:"कसरी जप गर्ने?"},howto_p:{hi:"शांत स्थान पर बैठें, रीढ़ सीधी रखें। आंखें बंद करके पहले 3 गहरी सांसें लें। फिर धीरे-धीरे, प्रत्येक शब्द को अनुभव करते हुए जपें। गिनती के लिए 108 मनकों की माला या उंगलियों का प्रयोग करें। जप के बाद 2 मिनट मौन बैठें, यही मौन आपके शिशु तक पहुंचता है।",en:"Sit in a quiet place with a straight spine. Close your eyes and take 3 deep breaths. Then chant slowly, feeling each word. Use a 108-bead mala or your fingers to count. Sit in silence for 2 minutes afterward, that silence reaches your baby.",ne:"शान्त ठाउँमा मेरुदण्ड सीधा राखेर बस्नुहोस्। आँखा बन्द गर्नुहोस् र ३ पटक गहिरो सास लिनुहोस्। त्यसपछि प्रत्येक शब्दलाई महसुस गर्दै बिस्तारै जप गर्नुहोस्। १०८-मणिको माला वा औंलाहरू प्रयोग गरेर गन्नुहोस्। त्यसपछि २ मिनेट मौन बस्नुहोस्, त्यो मौनता तपाईंको बच्चासम्म पुग्छ।"},a_title:{hi:"परिचय",en:"About",ne:"बारेमा"},trad_t:{hi:"गर्भ संस्कार की परंपरा",en:"The tradition of Garbh Sanskar",ne:"गर्भ संस्कारको परम्परा"},trad_p1:{hi:"गर्भ संस्कार का अर्थ है, गर्भ में ही संस्कार। यह मान्यता है कि शिशु की शिक्षा जन्म के बाद नहीं, गर्भ से ही आरंभ होती है। चरक संहिता में मासानुमासिक गर्भ वृद्धि का वर्णन है, महीने-दर-महीने भ्रूण का विकास, हजारों वर्ष पूर्व।",en:"Garbh Sanskar means sanskars in the womb, the belief that a child's education begins not after birth, but in the womb. The Charaka Samhita describes masanumasika garbha vriddhi, the month-by-month growth of the embryo, thousands of years ago.",ne:"गर्भ संस्कार भनेको गर्भमा गरिने संस्कार हो, यो विश्वास हो कि बच्चाको शिक्षा जन्म पछि होइन, तर गर्भमा सुरु हुन्छ। चरक संहिताले हजारौं वर्ष पहिले महिना-दर-महिना भ्रूणको वृद्धि, मासानुमासिक गर्भवृद्धि, वर्णन गर्दछ।"},trad_p2:{hi:"हमारे सोलह संस्कारों में से दो गर्भ से जुड़े हैं: पुंसवन (गर्भ के तीसरे-चौथे महीने में, स्वस्थ शिशु की कामना) और सीमंतोन्नयन (छठे-आठवें महीने में, माँ का श्रृंगार और आशीर्वाद, जिसे आज गोदभराई कहते हैं)।",en:"Two of our sixteen sanskars relate to the womb: Punsavana (in the third or fourth month, wishing for a healthy child) and Simantonnayana (in the sixth to eighth month, adorning the mother with blessings, known today as godh bharai).",ne:"हाम्रा सोह्र संस्कारहरूमध्ये दुई गर्भसँग सम्बन्धित छन्: पुंसवन (तेस्रो वा चौथो महिनामा, स्वस्थ बच्चाको कामना गर्दै) र सिमन्तोन्नयन (छैटौं देखि आठौं महिनामा, आमालाई आशीर्वादले सजाउने, जसलाई आज गोध भराई भनिन्छ)।"},trad_p3:{hi:"पुराणों की कथाएं इस परंपरा की आत्मा हैं: महाभारत के अभिमन्यु ने माँ सुभद्रा के गर्भ में ही चक्रव्यूह भेदन सीखा था, और भागवत के प्रह्लाद ने गर्भ में ही नारद मुनि से भक्ति का ज्ञान पाया था।",en:"The Puranic stories are the soul of this tradition: Abhimanyu of the Mahabharata learned to break the Chakravyuha while still in his mother Subhadra's womb, and Prahlad of the Bhagavata received the wisdom of devotion from sage Narada before birth.",ne:"पुराणिक कथाहरू यस परम्पराको आत्मा हुन्: महाभारतका अभिमन्युले आफ्नी आमा सुभद्राको गर्भमा हुँदा नै चक्रव्यूह तोड्न सिकेका थिए, र भागवतका प्रह्लादले जन्मनुअघि नै ऋषि नारदबाट भक्तिको ज्ञान प्राप्त गरेका थिए।"},sci_t:{hi:"आधुनिक विज्ञान क्या कहता है?",en:"What does modern science say?",ne:"आधुनिक विज्ञानले के भन्छ?"},sci_p:{hi:"आज का विज्ञान परंपरा की पुष्टि करता है: गर्भ में शिशु 18वें सप्ताह से सुनने लगता है, माँ की आवाज़ पहचानता है, संगीत पर प्रतिक्रिया देता है, और माँ के तनाव के हार्मोन (कोर्टिसोल) को अनुभव करता है। शांत मन, मधुर ध्वनि और सकारात्मक भाव, यही आधुनिक भाषा में गर्भ संस्कार है।",en:"Today's science confirms tradition: in the womb the baby begins to hear from the 18th week, recognizes the mother's voice, responds to music, and senses her stress hormones (cortisol). A calm mind, sweet sounds and positive emotions, that is Garbh Sanskar in modern language.",ne:"आजको विज्ञानले परम्परालाई पुष्टि गर्छ: गर्भमा बच्चाले १८ औं हप्तादेखि सुन्न थाल्छ, आमाको आवाज चिन्छ, संगीतमा प्रतिक्रिया दिन्छ, र उनको तनाव हार्मोन (कोर्टिसोल) महसुस गर्छ। शान्त मन, मीठो आवाज र सकारात्मक भावनाहरू, जुन आधुनिक भाषामा गर्भ संस्कार हो।"},gj_t:{hi:"गर्भ ज्योति के बारे में",en:"About GarbhaJyoti",ne:"गर्भज्योतिको बारेमा"},gj_p1:{hi:"गर्भ ज्योति एक वीडियो-प्रधान पहल है: YouTube पर छोटे-छोटे वीडियो और यह पोर्टल, सप्ताह-दर-सप्ताह मार्गदर्शन, शिशु नाम संग्रह, मंत्र और प्रार्थनाएं। लक्ष्य सरल है: हर गर्भवती माँ तक परंपरा का यह ज्ञान उसकी अपनी भाषा में पहुंचे।",en:"GarbhaJyoti is a video-first initiative: short videos on YouTube and this portal, week-by-week guidance, a baby name collection, mantras and prayers. The goal is simple: bring this traditional wisdom to every expecting mother in her own language.",ne:"गर्भज्योति एउटा भिडियो-प्रथम पहल हो: युट्युब र यस पोर्टलमा छोटो भिडियोहरू, हप्ता-दर-हप्ता मार्गदर्शन, बच्चाको नाम संग्रह, मन्त्र र प्रार्थनाहरू। लक्ष्य सरल छ: यो परम्परागत ज्ञान प्रत्येक गर्भवती आमालाई उनको आफ्नै भाषामा पुर्‍याउनुहोस्।"},trans_p:{hi:"पारदर्शिता: इस पोर्टल की सामग्री AI की सहायता से तैयार की जाती है और परंपरा व विज्ञान के स्रोतों से मार्गदर्शित होती है। यह चिकित्सकीय परामर्श का विकल्प नहीं है, किसी भी स्वास्थ्य निर्णय से पहले अपने डॉक्टर से अवश्य परामर्श लें।",en:"Transparency: this portal's content is prepared with AI assistance and guided by traditional and scientific sources. It is not a substitute for medical advice, always consult your doctor before any health decision.",ne:"पारदर्शिता: यस पोर्टलको सामग्री एआईको सहयोगमा तयार पारिएको छ र परम्परागत र वैज्ञानिक स्रोतहरूद्वारा निर्देशित छ। यो चिकित्सा सल्लाहको विकल्प होइन, कुनै पनि स्वास्थ्य निर्णय गर्नु अघि सधैं आफ्नो डाक्टरसँग परामर्श गर्नुहोस्।"},join_t:{hi:"जुड़ें",en:"Connect",ne:"जडान गर्नुहोस्"},join_p:{hi:"नए वीडियो हर सप्ताह:",en:"New videos every week:",ne:"हरेक हप्ता नयाँ भिडियोहरू:"}},t:function(e,n){var a=this.STR[e];if(!a)return e;var i=a[this.lang]||a.hi;return n&&Object.keys(n).forEach(function(e){i=i.replace("{"+e+"}",n[e])}),i},setLang:function(e){this.lang=e;try{localStorage.setItem("gj-lang",e)}catch(e){}document.documentElement.lang="en"===e?"en":"ne"===e?"ne":"hi",this.apply(),"function"==typeof window.onLangChange&&window.onLangChange()},apply:function(){var e=this;document.querySelectorAll("[data-i18n]").forEach(function(n){var a=n.getAttribute("data-i18n");"INPUT"===n.tagName&&"search"===n.type?n.placeholder=e.t(a):n.innerHTML=e.t(a)}),document.querySelectorAll(".lang-toggle button").forEach(function(n){n.classList.toggle("sel",n.getAttribute("data-lang")===e.lang)})}};